import 'package:flutter/material.dart';import '../../../core/network/football_repository.dart';
class FanProgressScreen extends StatefulWidget{const FanProgressScreen({super.key});@override State<FanProgressScreen> createState()=>_FanProgressScreenState();}
class _FanProgressScreenState extends State<FanProgressScreen>{final repo=FootballRepository();late Future<List<dynamic>>challenges;late Future<Map<String,dynamic>>level;@override void initState(){super.initState();challenges=repo.challenges();level=repo.level();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Fan Progress')),body:ListView(padding:const EdgeInsets.all(16),children:[FutureBuilder<Map<String,dynamic>>(future:level,builder:(c,s){if(!s.hasData)return const LinearProgressIndicator();final l=s.data!;return Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Level ${l['level']??1} • ${l['title']??'Rookie'}',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:8),Text('${l['xp']??0} XP • streak ${l['prediction_streak']??0}')])));}),const SizedBox(height:12),Text('Challenges',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w900)),FutureBuilder<List<dynamic>>(future:challenges,builder:(c,s)=>Column(children:(s.data??[]).map((x)=>Card(child:ListTile(title:Text('${x['title']}'),subtitle:Text('${x['creator']?['username']} vs ${x['opponent']?['username']}'),trailing:Chip(label:Text('${x['status']}'))))).toList()))]));}
